import type { LanguageModelV3Prompt } from '@ai-sdk/provider';

/**
 * GigaChat message format.
 *
 * Key differences from OpenAI:
 * - Tool results use role 'function' (not 'tool')
 * - Assistant tool use is via 'function_call' (not 'tool_calls')
 * - function_call.arguments is a parsed object, not a JSON string
 */
export interface GigaChatMessage {
  role: 'system' | 'user' | 'assistant' | 'function';
  content?: string;
  name?: string;
  function_call?: {
    name: string;
    arguments: Record<string, unknown>;
  };
}

export function convertToGigaChatChatMessages(
  prompt: LanguageModelV3Prompt,
): GigaChatMessage[] {
  const messages: GigaChatMessage[] = [];

  for (const message of prompt) {
    switch (message.role) {
      case 'system': {
        messages.push({ role: 'system', content: message.content });
        break;
      }

      case 'user': {
        const text = message.content
          .filter((p) => p.type === 'text')
          .map((p) => p.text)
          .join('');

        if (text) {
          messages.push({ role: 'user', content: text });
        }
        break;
      }

      case 'assistant': {
        let text = '';
        // GigaChat only supports a single function_call per message.
        // If multiple tool-call parts are present, only the last one is kept.
        let functionCall: GigaChatMessage['function_call'] = undefined;

        for (const part of message.content) {
          if (part.type === 'text') {
            text += part.text;
          } else if (part.type === 'tool-call') {
            const args = part.input;
            functionCall = {
              name: part.toolName,
              arguments:
                typeof args === 'string' ? JSON.parse(args) : (args as Record<string, unknown>),
            };
          }
        }

        const msg: GigaChatMessage = {
          role: 'assistant',
          content: text || undefined,
        };
        if (functionCall) {
          msg.function_call = functionCall;
        }
        messages.push(msg);
        break;
      }

      case 'tool': {
        for (const part of message.content) {
          if (part.type !== 'tool-result') continue;

          const output = part.output;
          let content: string;

          if (output == null) {
            content = '';
          } else if (typeof output === 'string') {
            content = output;
          } else if (typeof output === 'object' && 'type' in output) {
            const typed = output as { type: string; value?: unknown };
            switch (typed.type) {
              case 'text':
              case 'error-text':
                content = String(typed.value);
                break;
              case 'json':
              case 'error-json':
              case 'content':
                content = JSON.stringify(typed.value);
                break;
              default:
                content = JSON.stringify(output);
            }
          } else {
            content = JSON.stringify(output);
          }

          // GigaChat requires function result content to be valid JSON
          let jsonContent: string;
          try {
            JSON.parse(content);
            jsonContent = content;
          } catch {
            jsonContent = JSON.stringify(content || '');
          }

          messages.push({
            role: 'function',
            name: part.toolName,
            content: jsonContent,
          });
        }
        break;
      }
    }
  }

  return messages;
}

/**
 * Maps GigaChat finish_reason to AI SDK finish reason string.
 *
 * GigaChat reasons: 'stop', 'length', 'function_call', 'blacklist', 'error'
 */
export function mapGigaChatFinishReason(
  raw: string | null | undefined,
): string {
  if (!raw) return 'other';
  switch (raw) {
    case 'stop':
      return 'stop';
    case 'length':
      return 'length';
    case 'function_call':
      return 'tool-calls';
    case 'blacklist':
      return 'content-filter';
    case 'error':
      return 'error';
    default:
      return 'other';
  }
}

export interface GigaChatChatSettings {
  /**
   * Whether to enable profanity/content filtering.
   */
  profanityCheck?: boolean;

  /**
   * Repetition penalty for words (GigaChat-specific).
   */
  repetitionPenalty?: number;

  /**
   * Update interval for streaming responses, in seconds.
   */
  updateInterval?: number;

  /**
   * Feature flags to pass to the GigaChat API.
   */
  flags?: string[];
}

import type {
  LanguageModelV3FunctionTool,
  LanguageModelV3ProviderTool,
  LanguageModelV3ToolChoice,
  SharedV3Warning,
} from '@ai-sdk/provider';

export interface GigaChatFunction {
  name: string;
  description: string;
  parameters: Record<string, unknown>;
}

export interface GigaChatPreparedTools {
  functions: GigaChatFunction[] | undefined;
  functionCall: string | { name: string } | undefined;
  toolWarnings: SharedV3Warning[];
}

/**
 * Converts AI SDK tool definitions to GigaChat function format.
 *
 * GigaChat uses the older "functions" API (not "tools"), so we convert
 * AI SDK tool definitions into GigaChat-compatible function definitions.
 */
export function gigaChatPrepareTools(
  tools: Array<LanguageModelV3FunctionTool | LanguageModelV3ProviderTool> | undefined,
  toolChoice: LanguageModelV3ToolChoice | undefined,
): GigaChatPreparedTools {
  const toolWarnings: SharedV3Warning[] = [];

  if (!tools?.length) {
    return { functions: undefined, functionCall: undefined, toolWarnings };
  }

  const functions: GigaChatFunction[] = [];

  for (const tool of tools) {
    if (tool.type === 'function') {
      const schema = tool.inputSchema ?? { type: 'object', properties: {} };

      // Warn when the schema looks empty — this typically happens when
      // tool() is called with a zod v4 `parameters` key instead of
      // `inputSchema` + `jsonSchema()`.  The AI SDK serialises such
      // schemas as {"properties":{},"additionalProperties":false}, which
      // makes GigaChat ignore every parameter the tool should receive.
      const props = (schema as Record<string, unknown>).properties;
      if (
        props &&
        typeof props === 'object' &&
        Object.keys(props).length === 0
      ) {
        toolWarnings.push({
          type: 'other',
          message:
            `Tool "${tool.name}" has an empty inputSchema — parameters will not be sent to the model. ` +
            'If you defined the tool with a zod `parameters` key, switch to ' +
            '`inputSchema: jsonSchema(…)` instead (AI SDK v6 + zod v4 compatibility issue).',
        });
      }

      functions.push({
        name: tool.name,
        description: tool.description ?? '',
        parameters: schema,
      });
    } else {
      toolWarnings.push({
        type: 'unsupported',
        feature: `tool type "${tool.type}"`,
      });
    }
  }

  if (functions.length === 0) {
    return { functions: undefined, functionCall: undefined, toolWarnings };
  }

  let functionCall: string | { name: string } | undefined = undefined;

  if (toolChoice) {
    switch (toolChoice.type) {
      case 'auto':
        functionCall = 'auto';
        break;
      case 'none':
        functionCall = 'none';
        break;
      case 'required':
        // GigaChat doesn't have "required" — use "auto" as approximation
        functionCall = 'auto';
        toolWarnings.push({
          type: 'unsupported',
          feature: 'toolChoice.required',
          details: 'GigaChat does not support required tool choice, using auto',
        });
        break;
      case 'tool':
        functionCall = { name: toolChoice.toolName };
        break;
    }
  }

  return { functions, functionCall, toolWarnings };
}
